&lt;p style=&quot;line-height: 1.3; text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: &#39;trebuchet ms&#39;, geneva, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;95-120K annual base compensation&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
